mapper.sql:
SELECT DISTINCT #{taxClass_01} taxClass, portfolio_id portfolioId /*组合代码*/, PORTFOLIO_NAME portfolioName, finprod_id finprodId, /*产品代码*/ FINPROD_ABBR finprodAbbr, /*产品简称*/ FINPROD_MARKET_ID finprodMarketId, '' channelId, '' channelName, tradeId, totleTradeId, trade_Status tradeStatus, /*有效状态*/ ccy, /*币种*/ vDate, /*缴税/退税开始日*/ mDate, /*缴税/退税结束日*/ seitleDate, /*缴税/退税日期*/ interestIncome, /*利息收入*/ dividendIncome, /*红利收入*/ difbetIncome, /* 价差收入*/ interestIncome + dividendIncome + difbetIncome appreciationTax, /*增值税*/ constructionTax, /*城建税附加*/ educationTax, /*教育税附加*/ placeeducationTax, /*地方教育费附加*/ waterTrafficTax, /*水利基金税*/ constructionTax + educationTax + placeeducationTax + waterTrafficTax additionalTax, /* 增值税附加*/ Trade_Amt taxTotal, /*税费总额*/ ACCT_NAME actName, taxidenType /*类型*/ FROM ( SELECT TPD.TOTLE_TRADE_ID totleTradeId, TPD.TRADE_ID tradeId, TPD.PS taxidenType, tpa.portfolio_id, ptl.PORTFOLIO_NAME, /*组合名称*/ prd.finprod_id, prd.FINPROD_MARKET_ID, prd.FINPROD_ABBR, TPD.Trade_Amt, tpd.ccy, to_char(TPD.VDATE, 'yyyy-MM-dd') vDate, to_char(TPD.MDATE, 'yyyy-MM-dd') mDate, to_char(TPD.SETTLE_DATE, 'yyyy-MM-dd') seitleDate, NVL((SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{TAX0102}), 0) interestIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{TAX0202}) dividendIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{TAX0302}) difbetIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{ALT0102}) constructionTax, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{ALT0202}) educationTax, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{ALT0302}) placeeducationTax, nvl((SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{ALT0402}),0) waterTrafficTax, TPD.TRADE_STATUS, stli.ACCT_NAME, TPD.Finprod_Type, TPD.Finprod_Type2 FROM TRD_PRODUCT_DEAL TPD left join trd_product_deal_add tpa on tpd.trade_id = tpa.trade_id left join fin_product prd on tpd.finprod_id = prd.finprod_id left join stl_pay_orders stl on TPD.TOTLE_TRADE_ID = stl.trade_id left join STL_CAPACCT_INFO stli on decode(stl.ps, #{ps01}, stl.MY_ACCT_NO, stl.COUNTER_ACCT_NO) = stli.acct_no left join PTL_PORTFOLIO ptl on tpa.portfolio_id = ptl.portfolio_id where TPD.BUSI_TYPE = #{busiType16} and TPD.Finprod_Type = #{finprodType} and TPD.Finprod_Type2 = #{finprodType2} /*and tpd.chl_id is null*/ /*modify by jiangpeng on 20210512 ZGBSSE-367 通道户增值税,不能屏蔽通道交易*/ and not exists ( select 1 from TRD_PRODUCT_DEAL b where b.P_TRADE_ID = TPD.TRADE_ID )
and TPD.CCY = #{ccy}
and TPD.TRADE_STATUS = #{tradeStatus}
and TPD.FINPROD_ID = #{finprodId}
and TPD.PS = #{taxidenType}
and TPD.TRADE_DATE >= #{vatDateBegin}
and TPD.TRADE_DATE <= #{vatDateEnd}
and tpa.portfolio_id in
#{item}
and TPD.TOTLE_TRADE_ID in
#{item}
)

select #{taxClass_02} taxClass, portfolioId, portfolioName, '' finprodId, '' finprodAbbr, '' finprodMarketId, channelId, channelName, tradeId, totleTradeId, tradeStatus, ccy, vdate, mdate, seitleDate, interestIncome, /*利息收入*/ dividendIncome, /*红利收入*/ difbetIncome, /* 价差收入*/ interestIncome + dividendIncome + difbetIncome appreciationTax, /*增值税*/ constructionTax, /*城建税附加*/ educationTax, /*教育税附加*/ placeeducationTax, /*地方教育费附加*/ waterTrafficTax, /*水利基金税*/ constructionTax + educationTax + placeeducationTax + waterTrafficTax additionalTax, /* 增值税附加*/ tradeAmt, actName, taxidenType from( select ad.portfolio_id portfolioId, ptl.portfolio_name portfolioName, f.finprod_market_id channelId, f.finprod_abbr channelName, deal.totle_trade_id totleTradeId, deal.trade_id tradeId, deal.trade_status tradeStatus, deal.finprod_type2, deal.ccy, to_char(deal.vdate, 'yyyy-mm-dd') vdate, to_char(deal.mdate, 'yyyy-mm-dd') mdate, to_char(deal.settle_date, 'yyyy-mm-dd') seitleDate, stli.ACCT_NAME actName, deal.trade_amt tradeAmt, deal.ps taxidenType, NVL((SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{TAX0102}), 0) interestIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{TAX0202}) dividendIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{TAX0302}) difbetIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{ALT0102}) constructionTax, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{ALT0202}) educationTax, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{ALT0302}) placeeducationTax, nvl((SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{ALT0402}), 0) waterTrafficTax from trd_product_deal deal inner join fin_product f on deal.chl_id = f.finprod_id and f.finprod_type2 = #{finprodType2_F28} left join trd_product_deal_add ad on ad.trade_id = deal.trade_id left join ptl_portfolio ptl on ptl.portfolio_id = ad.portfolio_id left join stl_pay_orders stl on deal.TOTLE_TRADE_ID = stl.trade_id left join STL_CAPACCT_INFO stli on decode(stl.ps, #{ps01}, stl.MY_ACCT_NO, stl.COUNTER_ACCT_NO) = stli.acct_no where 1=1 and deal.busi_type = #{busiType16} and deal.Finprod_Type = #{finprodType} and deal.Finprod_Type2 = #{finprodType2} and not exists (select 1 from TRD_PRODUCT_DEAL b where b.P_TRADE_ID = deal.TRADE_ID)
and f.finprod_market_id = #{channelId}
and deal.TRADE_DATE >= #{vatDateBegin}
and deal.TRADE_DATE <= #{vatDateEnd}
and deal.PS = #{taxidenType}
and deal.TRADE_STATUS = #{tradeStatus}
and ad.portfolio_id in
#{item}
)

mapper.select:
SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text, B.IS_GUARANTEE object FROM PTL_PORTFOLIO A LEFT JOIN PA_PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID 1=1 AND A.PARENT_PORTFOLIO_ID IS NULL
AND (A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.PORTFOLIO_ID = #{initValue}

select fin_product.finprod_market_id id, fin_product.finprod_abbr text,
fin_product.finprod_id finprodId,
fin_product.finprod_id || ',' || fin_product_add.pay_type object from fin_product left join fin_product_add on fin_product_add.finprod_id = fin_product.finprod_id 1=1 and fin_product.finprod_type2 = #{finprodType2_F28}
AND (fin_product.finprod_market_id LIKE CONCAT('%', CONCAT(#{search}, '%')) OR fin_product.finprod_abbr LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND fin_product.finprod_market_id = #{initValue}
